import { linkWallet } from "@kybernesis/payments";

// Stripe Link as the agent's wallet, behind the OWNER's link-cli sign-in on
// this host (`npx link-cli auth login --client-name <agent>`; the owner
// approves in the Link app). Tools: link__create_spend_request and friends.
// Every purchase is approved by the person in Link before a card exists.
export default linkWallet();

import { payOnComputerTool } from "@kybernesis/payments";

// Types the one-time card of an APPROVED spend request into the checkout open
// in the agent's own browser. The card goes Link → page; the model only learns
// which fields were filled.
export default payOnComputerTool();

import { defineInstructions } from "eve/instructions";
import { PAYMENTS_INSTRUCTIONS } from "@kybernesis/payments";

// Agree the exact total first, ask (spend request), wait for Link's approval,
// fill the card without seeing it, screenshot, submit, report.
export default defineInstructions({ content: PAYMENTS_INSTRUCTIONS });
